import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.ChTAMbUy.js";const g=JSON.parse('{"title":"API Keys","description":"","frontmatter":{},"headers":[],"relativePath":"1.10/platform/api_keys.md","filePath":"versions/1.10/platform/api_keys.md","lastUpdated":1795427687000}'),o={name:"1.10/platform/api_keys.md"};function r(n,e,l,h,d,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="api-keys" tabindex="-1">API Keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API Keys&quot;">​</a></h1><p>API keys provide scoped programmatic access to selected prokube services without a browser session. Use them wherever a script, CI job, or external client calls a prokube service.</p><p>Each key can be scoped to specific services/workloads instead of the whole workspace, sent with either of two client authentication headers, and given an optional expiration date.</p><p>A key belongs to the workspace that was selected when it was created. prokube routes public API traffic through <a href="./agent_gateway.html">Agent Gateway</a>, the shared routing and policy layer for API clients, but you do not need to configure Agent Gateway to create a key.</p><p>Use API keys when a workload or external client needs repeatable access without an interactive login. For browser-based work in the prokube UI, use your normal user session instead.</p><h2 id="manage-keys-in-the-ui" tabindex="-1">Manage Keys in the UI <a class="header-anchor" href="#manage-keys-in-the-ui" aria-label="Permalink to &quot;Manage Keys in the UI&quot;">​</a></h2><p>Open <strong>API Keys</strong> from the sidebar under <strong>Serving</strong>. Select the workspace before creating or editing keys.</p><p>Regular users see only their own keys in the selected workspace. Administrators can see and manage all keys in the workspace.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/api-keys/api-keys-list-last-active-framed.png" alt="API Keys list with owner, scopes, rate limit, and last activity per key" loading="lazy"></p><p>The table shows each key&#39;s metadata, such as owner, status, scopes, client authentication, creation and expiration date, but never the full key value. The key prefix helps identify which key a client is using without exposing the secret. <strong>Rate Limit</strong> appears only when the platform enforces <a href="#request-limits">request limits</a>.</p><p><strong>Last active</strong> shows when the key was last used, looking back over the longest usage window (10 days by default):</p><ul><li>a relative time, such as <strong>about 2 hours ago</strong>;</li><li><strong>No calls in N days</strong>: the whole window is covered by logs and the key made no calls;</li><li><strong>No calls logged</strong>: no calls were found, but the gateway logs start later than the window, so older calls are unknown;</li><li><strong>—</strong>: usage data or log coverage is unknown.</li></ul><p><strong>View usage</strong> opens <a href="./gateway_usage.html">Gateway Usage</a> with the per-key breakdown.</p><h2 id="ownership-and-workspace-scope" tabindex="-1">Ownership and Workspace Scope <a class="header-anchor" href="#ownership-and-workspace-scope" aria-label="Permalink to &quot;Ownership and Workspace Scope&quot;">​</a></h2><p>API keys are scoped by both workspace and owner:</p><ul><li>A key can only grant access inside the workspace where it was created.</li><li>Regular users can list, edit, rotate, disable, and delete only their own keys.</li><li>Administrators can list and manage all keys in the selected workspace.</li></ul><p>For shared automation, avoid personal long-lived keys where possible. Prefer a key created by the user or service account that owns the automation, and document where the secret is stored.</p><h2 id="create-a-key" tabindex="-1">Create a Key <a class="header-anchor" href="#create-a-key" aria-label="Permalink to &quot;Create a Key&quot;">​</a></h2><p>Click <strong>Create Key</strong> and fill in the form:</p><ul><li><strong>Name</strong>: a descriptive name for the key.</li><li><strong>Description</strong>: optional context for who or what uses the key.</li><li><strong>Expiration Date</strong>: optional. Use expirations for automation keys unless there is a clear rotation process.</li><li><strong>Requests Per Minute</strong>: optional, shown only when the platform enforces <a href="#request-limits">request limits</a>. Leave it empty for unlimited.</li><li><strong>Client Authentication</strong>: choose how clients send the key.</li><li><strong>Select Services</strong>: choose the services this key may access.</li></ul><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/api-keys/create-key-ui.png" alt="Create API Key dialog with client authentication and service selection" loading="lazy"></p><p>The service list is built from services available in the selected workspace. It can include:</p><ul><li><strong>Models</strong> for KServe and LLM endpoints.</li><li><strong>MCP servers</strong> for tool access.</li><li><strong>Memory stores</strong> exposed through MCP-compatible routes.</li><li><strong>A2A agents</strong> for kagent agent-to-agent access.</li><li><strong>Knative services</strong> exposed through gateway routes.</li></ul><p>Besides individual services, you can select aggregate scopes such as <strong>All MCP servers</strong> or <strong>All AI models</strong>. They also cover matching services created later. <strong>Full workspace access</strong> covers every service in the workspace. Keys with <strong>All AI models</strong>, <strong>All external AI models</strong>, or <strong>Full workspace access</strong> must use the Bearer format.</p><p><strong>All sandboxes</strong> lets the <code>pk</code> CLI and the Python SDK manage and use the workspace&#39;s <a href="./../agentops/sandboxes.html#external-access-with-api-keys">sandboxes</a>. Such keys must use the Bearer format; <strong>Full workspace access</strong> does not include sandboxes.</p><p>Admin-granted <a href="./../admin/external_models.html">external models</a> are not listed as individual services. To reach them, use a Bearer-format key with <strong>All external AI models</strong>, <strong>All AI models</strong>, or <strong>Full workspace access</strong>. These scopes cover every granted model in the workspace; a key cannot be limited to one granted model.</p><p>Select only the services the client needs. If no services are available, deploy or expose the service first, then create the key.</p><p>Service-specific scopes are the default choice for production clients. They reduce blast radius if a key is exposed and make it clear which integration depends on which platform service.</p><h2 id="client-authentication" tabindex="-1">Client Authentication <a class="header-anchor" href="#client-authentication" aria-label="Permalink to &quot;Client Authentication&quot;">​</a></h2><p>Choose the authentication format expected by the client:</p><table tabindex="0"><thead><tr><th>Format</th><th>Use when</th></tr></thead><tbody><tr><td><code>Authorization: Bearer &lt;key&gt;</code></td><td>The client is OpenAI-compatible or expects bearer authentication. This is the recommended format for LLM clients.</td></tr><tr><td><code>x-api-key: &lt;key&gt;</code></td><td>The client cannot set an <code>Authorization</code> header, or an existing integration already sends <code>x-api-key</code>. Not available for keys with <strong>All AI models</strong>, <strong>All external AI models</strong>, <strong>All sandboxes</strong>, or <strong>Full workspace access</strong>.</td></tr></tbody></table><p>Use the service page for the exact URL and request body. Examples:</p><p>OpenAI-compatible model clients commonly use bearer authentication. For a model deployed through <a href="./../agentops/llm_serving.html">LLM Serving</a>, <code>&lt;route-id&gt;</code> is the deployment name; for an admin-granted <a href="./../admin/external_models.html">external model</a>, it is the route ID chosen in the grant:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://&lt;your-prokube-domain&gt;/svc/ai/&lt;workspace&gt;/models/&lt;route-id&gt;/v1/chat/completions&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;api-key&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;model&quot;:&quot;&lt;model&gt;&quot;,&quot;messages&quot;:[{&quot;role&quot;:&quot;user&quot;,&quot;content&quot;:&quot;Hello&quot;}]}&#39;</span></span></code></pre></div><p>MCP clients take the key in their server configuration. The MCP server&#39;s <strong>Overview</strong> tab in the prokube UI shows a ready-to-copy configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;&lt;server&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://&lt;your-prokube-domain&gt;/svc/mcp/&lt;workspace&gt;/&lt;server&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer &lt;api-key&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="copy-the-key-value" tabindex="-1">Copy the Key Value <a class="header-anchor" href="#copy-the-key-value" aria-label="Permalink to &quot;Copy the Key Value&quot;">​</a></h2><p>prokube shows the full key value only after creation or rotation. Copy it immediately and store it in your secret manager.</p><p>If you close the dialog without copying the key, create a new key or rotate the existing key. The old full value cannot be recovered from the UI.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/api-keys/api-key-shown-once.png" alt="One-time API key display with copy action and client example" loading="lazy"></p><h2 id="manage-existing-keys" tabindex="-1">Manage Existing Keys <a class="header-anchor" href="#manage-existing-keys" aria-label="Permalink to &quot;Manage Existing Keys&quot;">​</a></h2><p>From the API Keys page you can:</p><ul><li>search keys by name or prefix;</li><li>filter by status, expiration, and scope type;</li><li>edit metadata, expiration, request limit, enabled state, and service scopes;</li><li>open a key&#39;s <a href="#request-activity">Request Activity</a>;</li><li>disable, rotate, or delete keys.</li></ul><p>Disable a key when you need temporary revocation or want to test whether a client still depends on it. Delete a key when it is no longer needed.</p><p>Rotating a key invalidates the old value immediately. Update every client or secret that uses the key before relying on the rotated value.</p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/api-keys/api-key-actions-menu-activity-framed.png" alt="API key action menu with Activity, Edit, Disable, Rotate key value, and Delete" style="max-width:360px;width:100%;height:auto;"><h2 id="request-limits" tabindex="-1">Request Limits <a class="header-anchor" href="#request-limits" aria-label="Permalink to &quot;Request Limits&quot;">​</a></h2><p>Use a per-key request limit to protect services from runaway clients, such as a script stuck in a retry loop. A limit is not a usage quota.</p><p>Request limits are an optional platform feature and are disabled by default. A platform administrator can enable them; see <a href="./../admin/operations_runbooks.html#api-key-request-limits">API Key Request Limits</a>. While they are disabled, the <strong>Requests Per Minute</strong> field and the <strong>Rate Limit</strong> column are hidden, and keys are not limited.</p><p>When limits are enabled, set <strong>Requests Per Minute</strong> when creating or editing a key, or leave it empty for unlimited. To remove a limit, clear the field in <strong>Edit</strong>.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/api-keys/api-key-create-rpm-limit-framed.png" alt="Create API Key dialog with a Requests Per Minute limit of 60" loading="lazy"></p><p>A client that exceeds the limit receives HTTP <code>429 Too Many Requests</code>. The limit works as follows:</p><ul><li>Every request attempt counts, including failed ones, across all services the key can reach.</li><li>Requests are counted in fixed one-minute windows, so a client can briefly send about twice the limit around a minute boundary.</li><li>A new or changed limit takes effect asynchronously.</li><li>If the rate-limit service is unavailable, requests are allowed.</li></ul><p>The <strong>Rate Limit</strong> column shows <code>Unlimited</code> or the limit, such as <code>60 / min</code>, with a status:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Propagated</strong></td><td>Every route the key can use carries the limit. No over-limit rejection in the last hour.</td></tr><tr><td><strong>Limited recently</strong></td><td>Agent Gateway rejected requests over the limit within the last hour. This does not confirm that the limiter is reachable right now.</td></tr><tr><td><strong>Pending</strong></td><td>Not every route the key can use carries the limit yet.</td></tr><tr><td><strong>Not enforced</strong> (grey)</td><td>No gateway policy carries the limit, for example because platform rate limiting is turned off.</td></tr><tr><td><strong>Not enforced</strong> (red)</td><td>The stored limit is invalid. Edit the key and set a valid limit, or select <strong>remove the stored limit</strong>.</td></tr><tr><td><strong>Status unknown</strong></td><td>The gateway policy state could not be read.</td></tr></tbody></table><h2 id="key-usage" tabindex="-1">Key Usage <a class="header-anchor" href="#key-usage" aria-label="Permalink to &quot;Key Usage&quot;">​</a></h2><p>Usage of all keys in the workspace is shown on <a href="./gateway_usage.html">Gateway Usage</a>, together with model grants, internal calls, and other traffic. Select <strong>View usage</strong> on the API Keys page to open it on the <strong>By API key</strong> tab, which lists calls, LLM calls, failures, tokens, estimated cost, and last activity per key. Regular users see their own keys; platform administrators see all keys in the workspace.</p><h3 id="request-activity" tabindex="-1">Request Activity <a class="header-anchor" href="#request-activity" aria-label="Permalink to &quot;Request Activity&quot;">​</a></h3><p>Select <strong>Actions</strong> &gt; <strong>Activity</strong> on a key, or <strong>Activity</strong> in the key&#39;s row on Gateway Usage, to list the individual requests that Agent Gateway authenticated with that key. Regular users can open Activity for their own keys; administrators for any current key in the workspace. Deleted keys cannot open Activity.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/gateway-usage/gateway-usage-credential-activity-framed.png" alt="Request Activity for an API key with the call trend, filters, and individual calls" loading="lazy"></p><p>To see which models or services the key used, set <strong>Split by</strong> in the call trend to <strong>Model</strong> or <strong>Route</strong>.</p><p>Narrow the list with:</p><ul><li><strong>Time window</strong>: <strong>Last hour</strong>, <strong>Last 24 hours</strong> (default), <strong>Last 7 days</strong>, or <strong>Max (N days)</strong>, 10 days by default.</li><li><strong>HTTP status</strong>: one status code, for example <code>429</code>. Leave it empty for all statuses.</li><li><strong>Request model</strong>: the model ID the client requested.</li><li><strong>Caller</strong>: the full ID of the calling workload, for example <code>cluster.local/ns/&lt;workspace&gt;/sa/my-agent</code>, or <code>none</code> for calls through the public endpoint. A short name such as <code>my-agent</code> is rejected.</li></ul><p>Select <strong>Apply filters</strong> to load the filtered list and <strong>Refresh</strong> to reload it. Use <strong>Older</strong> and <strong>Newer</strong> to page through the results.</p><p>Each row is one request. For MCP calls, the row also shows the MCP method and tool; fields that do not apply, such as tokens, show a dash.</p><p><strong>Export CSV</strong> downloads the current page with the active filters, not the full history.</p><p>Activity is built from Agent Gateway access logs, which are kept for 10 days by default. It is an operational view, not a durable audit record. It shows request metadata only: prompts, responses, tool arguments, and credentials are not logged. If the logs cannot be read, the view shows <strong>Activity unavailable</strong> with a <strong>Retry</strong> action.</p><h2 id="security-guidance" tabindex="-1">Security Guidance <a class="header-anchor" href="#security-guidance" aria-label="Permalink to &quot;Security Guidance&quot;">​</a></h2><ul><li>Prefer service-specific keys over broad workspace access.</li><li>Set an expiration date for automation keys where possible.</li><li>Store keys in a secret manager, not in source code, notebooks, screenshots, shell history, or issues.</li><li>Rotate keys when ownership changes, a client is redeployed, or a key may have been exposed.</li><li>Disable a key first if you need to test impact before deleting it.</li><li>Delete keys that are no longer used.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>No services are available when creating a key</td><td>Confirm the target service exists in the selected workspace and is exposed through Agent Gateway-supported routes.</td></tr><tr><td>A key is not visible to another user in the same workspace</td><td>Regular users only see keys they created. Ask an administrator if shared visibility or management is required.</td></tr><tr><td>Client receives <code>401</code> or <code>403</code></td><td>Confirm the key is enabled, not expired, sent with the selected authentication header, and scoped to the target service.</td></tr><tr><td>Client can call one service but not another</td><td>The key is scoped to selected services. Edit the key or create a new key for the additional service.</td></tr><tr><td>Client stopped working after rotation</td><td>The old key value stopped working immediately. Update the client secret or environment variable with the new value.</td></tr><tr><td>Client receives <code>429</code></td><td>If the key has a <a href="#request-limits">request limit</a>, it may have exceeded it: slow the client down or raise the limit. Otherwise the model or its provider is limiting requests. Check the key&#39;s <a href="#request-activity">Request Activity</a> for status <code>429</code>.</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./gateway_usage.html">Gateway Usage</a></li><li><a href="./agent_gateway.html">Agent Gateway</a></li><li><a href="./../agentops/mcp_servers.html">MCP Servers</a></li><li><a href="./../mlops/model_serving.html">Model Serving</a></li><li><a href="./../mlops/knative.html">Serverless</a></li></ul>`,73)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
